# Store Sidebar Collapsed State

I'll add state management to persist the sidebar collapsed state in the UI store.

## Changes Summary

| File | Change | Reason |
|------|--------|--------|
| `src/store/ui.js` | Add `sidebarCollapsed` state and mutations | Persist sidebar state across sessions |
| `src/components/layout/DesktopSidebar.vue` | Save/load collapsed state from store | Restore sidebar state on mount |

## Updated Files

```js src/store/ui.js
export const state = () => ({
  showCoder: false,
  showBrowser: false,
  lastActiveTab: "",
  codxJuniorWidth: 30,
  isMobile: false,
  orientation: 'portrait',
  openedFile: null,
  showLogs: false,
  voiceLanguage: 'en-US',
  voiceLanguages: {
    "en-US": "English",
    "es-SP": "Español"
  },
  viewMode: 'expert',
  openApps: {},
  appDivided: 'horizontal',
  resolution: API.screen.display?.resolution,
  resolutions: API.screen.display?.resolutions,
  monitor: "preview",
  monitors: {
    "preview": "CODX-SCREEN-PREVIEW",
    "shared": "CODX-SCREEN-SHARED"
  },
  colorsMap: {},
  coderProjectCodxPath: null,
  uiReady: false,
  floatingCodxJunior: false,
  notifications: [],
  noVNCSettings: {
    resize: 'remote',
  },
  theme: 'dark',
  activeTab: 'home',
  newProject: false,
  activeApp: null,
  appShowMode: null,
  viewEditor: null,
  activeTeam: null,
  teamBarCollapsed: false,
  panelWidths: {
    chat: 30,
    changes: 33,
    preview: 37
  },
  sidebarCollapsed: false,
  projectLoadingState: {
    isLoading: false,
    projectName: '',
    currentStep: null,
    error: null
  }
})
```

```js src/store/ui.js (mutations section)
export const mutations = mutationTree(state, {
  setActiveTab(state, tab) {
    tab = tab || 'home'
    if (tab !== 'home') {
      $storex.ui.showApp({
        name: tab,
        component: tab
      })
    } else {
      state.activeTab = null
      state.activeApp = null
    }
    $storex.ui.saveState()
  },
  showTab(state, tab) {
    if (tab !== state.activeTab) {
      $storex.ui.setActiveTab(tab)
    }
    if (!state.isMobile) {
      $storex.ui.showApp({
        name: tab,
        component: tab
      })
    }
  },
  closeTab(state) {
    state.activeTab = null
  },
  setCodxJuniorWidth(state, width) {
    state.codxJuniorWidth = width
    $storex.ui.saveState()
  },
  toggleLogs(state) {
    state.showLogs = !state.showLogs
    $storex.ui.showApp({
      name: 'Logs',
      component: 'log-viewer'
    })
  },
  openChatLogs(state) {
    state.showLogs = !state.showLogs
    $storex.ui.showApp({
      name: 'Chat logs',
      component: 'chat-logs'
    })
  },
  setVoiceLanguage(state, voiceLanguage) {
    state.voiceLanguage = voiceLanguage
    $storex.ui.saveState()
  },
  setVibeMode(state) {
    state.viewMode = 'vibe'
    $storex.ui.saveState()
  },
  setExpertMode(state) {
    state.viewMode = 'expert'
    $storex.ui.saveState()
  },
  setViewMode(state, mode) {
    state.viewMode = mode
    $storex.ui.saveState()
  },
  setAppDivided(state, divided) {
    state.appDivided = divided
    $storex.ui.saveState()
  },
  setMonitor(state, monitor) {
    state.monitor = monitor
    $storex.ui.saveState()
  },
  setColorsMap(state, colorsMap) {
    state.colorsMap = colorsMap
    $storex.ui.saveState()
  },
  coderOpenPath(state, project) {
    state.coderProjectCodxPath = project.codx_path
  },
  setUIready(state) {
    $storex.ui.loadState()
    state.uiReady = true
  },
  setFloatinCodxJunior(state, floating) {
    state.floatingCodxJunior = floating
    $storex.ui.saveState()
  },
  toggleFloatinCodxJunior(state) {
    state.floatingCodxJunior = !state.floatingCodxJunior
    $storex.ui.saveState()
  },
  addNotification(state, { text, type }) {
    const existing = state.notifications?.find(n => n.text === text)
    if (existing) {
      existing.ts = moment().format("HH:mm:ss")
      return
    }
    const notif = {
      ts: moment().format("HH:mm:ss"),
      text,
      type: type || 'info'
    }
    state.notifications.push(notif)
    setTimeout(() => $storex.ui.removeNotification(notif), 30000)
  },
  removeNotification(state, notification) {
    state.notifications.splice(
      state.notifications.findIndex(n => n === notification), 1)
  },
  clearNotifications(state, notifications) {
    state.notifications = state.notifications.filter(n => !notifications.includes(n))
  },
  setNoVNCSettings(state, settings) {
    state.noVNCSettings = { ...state.noVNCSettings, ...settings }
  },
  setTheme(state, theme) {
    state.theme = theme
  },
  showNewProject(state, show) {
    state.newProject = show
  },
  cloneApp(state, app) {
    $storex.ui.showApp({ ...app, tabId: null })
  },
  resetOpenApps(state) {
    state.openApps = {}
    state.activeApp = null
  },
  showApp(state, app) {
    app.tabId = app.tabId || `${app.key || app.name}-${Date.now()}`
    app.params = app.params || {}
    // Auto-inject project_id if not present
    if (!app.params.project_id && $storex.projects.activeProject?.project_id) {
      app.params.project_id = $storex.projects.activeProject.project_id
    }
    app.initialParams = app.initialParams || JSON.parse(JSON.stringify(app.params))
    app.openedAt = Date.now()

    if (state.viewMode !== 'vibe' && !state.isMobile) {
      // Check if app already exists in openApps state
      const existingApp = Object.values(state.openApps).find(openApp => {
        if (app.key && openApp.key) {
          return openApp.key === app.key
        }
        return openApp.component === app.component && 
              JSON.stringify(openApp.initialParams) === JSON.stringify(app.initialParams)
      })

      if (existingApp) {
        state.activeApp = existingApp
        $storex.views.activatePanel(existingApp.tabId)
        return
      }

      // Check if panel already exists in Desktop API by checking component and initialParams
      const desktopApi = $storex.views._desktopApi
      if (desktopApi && desktopApi.panels) {
        const existingPanel = desktopApi.panels.find(panel => {
          if (app.key && panel.key) {
            return panel.key === app.key
          }
          const panelParams = panel.params?.params || panel.params || {}
          return panel.component === app.component && 
                JSON.stringify(panelParams.initialParams || panelParams) === JSON.stringify(app.initialParams)
        })

        if (existingPanel) {
          state.activeApp = app
          $storex.views.activatePanel(existingPanel.id)
          return
        }
      }
    }

    state.openApps = {
      ...state.openApps,
      [app.tabId]: app
    }
    state.activeApp = app
  },
  updateAppParams(state, { tabId, params }) {
    const app = state.openApps[tabId]
    if (!app) return
    state.openApps = {
      ...state.openApps,
      [tabId]: {
        ...app,
        params: {
          ...app.params,
          ...params
        }
      }
    }
  },
  closeApp(state, app) {
    if (!app) return
    delete state.openApps[app.tabId]
    if (state.activeApp?.tabId === app.tabId) {
      const remainingApps = Object.values(state.openApps)
      if (remainingApps.length > 0) {
        state.activeApp = remainingApps.reduce((latest, current) =>
          current.openedAt > latest.openedAt ? current : latest
        )
      } else {
        state.activeApp = null
      }
    }
    if (!Object.keys(state.openApps).length) {
      if (!state.activeTab) {
        $storex.ui.showTab(state.lastActiveTab || 'tasks')
      }
    }
    $storex.ui.saveState()
  },
  setAppShowMode(state, mode) {
    state.appShowMode = mode
  },
  setSidebarCollapsed(state, collapsed) {
    state.sidebarCollapsed = collapsed
    $storex.ui.saveState()
  },
  openChat(_, chat) {
    if (!$storex.ui.isDesktopMode) {
      $storex.$router.push({
        name: 'chat',
        params: {
          chatId: chat.id,
          chatName: chat.name
        }
      })
    } else {
      $storex.ui.showApp({
        tabId: chat.id,
        name: chat.name,
        component: 'chat',
        params: {
          chat: {
            id: chat.id,
            name: chat.name,
            owner_project_id: chat.owner_project_id
          }
        }
      })
    }
  },
  openFileInViewer(_, filePath) {
    const fileName = filePath.split('/').pop()
    $storex.ui.showApp({
      tabId: `file-viewer-${filePath}`,
      name: fileName,
      component: 'file-viewer',
      params: { filePath }
    })
  },
  openViewEditor(state, view = null) {
    state.viewEditor = { view: view || null }
  },
  closeViewEditor(state) {
    state.viewEditor = null
  },
  setActiveTeam(state, team) {
    state.activeTeam = team
    $storex.ui.saveState()
  },
  setTeamBarCollapsed(state, collapsed) {
    state.teamBarCollapsed = collapsed
    $storex.ui.saveState()
  },
  setPanelWidth(state, { panel, width }) {
    state.panelWidths = {
      ...state.panelWidths,
      [panel]: width
    }
    $storex.ui.saveState()
  },
  setProjectLoadingState(state, loadingState) {
    state.projectLoadingState = {
      ...state.projectLoadingState,
      ...loadingState
    }
  },
})
```

```vue src/components/layout/DesktopSidebar.vue
<script>
export default {
  props: {
    isMobile: { type: Boolean, default: false },
    isMobileExpanded: { type: Boolean, default: false }
  },
  emits: ['settings', 'close'],
  data() {
    return {
      isCollapsed: true,
      userCollapsed: false,
      resizeObserver: null,
      dailyLimitStatus: 'normal',
      moreExpanded: false
    }
  },
  computed: {
    workspaceApps() {
      return this.$projects.projectApps || []
    },
    currentUser() {
      return this.$storex?.users?.user || this.$user
    },
    hasWorkspaceApps() {
      return this.workspaceApps && this.workspaceApps.length > 0
    },
    isProjectAdmin() {
      return this.$users?.isProjectAdmin || false
    },
    currentWorkspaceId() {
      return this.$storex.$router.$navigation.getWorkspaceId()
    },
    isDesktopMode() {
      return this.$storex.$router.$navigation.isDesktopMode
    },
    userName() { 
      return this.$users.user?.username 
    },
    userSubtitle() {
      const email = this.$users.user?.email
      return email && email.length > 20 ? email.substring(0, 20) + '...' : email
    },
    connected() {
      return this.$session.connected
    },
    incomingCall() {
      const calls = this.$storex.calls.allIncomingCalls
      return calls.length > 0 ? calls[0] : null
    }
  },
  watch: {
    isMobileExpanded(val) {
      if (this.isMobile) {
        this.isCollapsed = !val
      }
    }
  },
  mounted() {
    if (!this.isMobile) {
      this.isCollapsed = this.$storex.ui.sidebarCollapsed
      this.$nextTick(() => this.setupResizeObserver())
    } else {
      this.isCollapsed = !this.isMobileExpanded
    }
  },
  beforeUnmount() {
    this.resizeObserver?.disconnect()
  },
  methods: {
    setupResizeObserver() {
      const el = this.$refs.sidebarEl
      if (!el) return
      const parent = el.parentElement
      if (!parent) return
      this.resizeObserver = new ResizeObserver(([entry]) => {
        const width = entry.contentRect.width
        if (!this.userCollapsed) {
          this.isCollapsed = width < 600
        }
      })
      this.resizeObserver.observe(parent)
    },
    toggleCollapse() {
      this.userCollapsed = !this.userCollapsed
      this.isCollapsed = this.userCollapsed
      this.$storex.ui.setSidebarCollapsed(this.isCollapsed)
    },
    handleClose() {
      if (this.isMobile) {
        this.isCollapsed = true
      }
      this.$emit('close')
    },
    handleSelectChat(chat) {
      this.$chats.setActiveChat(chat)
      if (this.isMobile) {
        this.handleClose()
      }
    },
    handleCallInitiated(callId) {
      console.log('Call initiated:', callId)
    },
    handleCallEnded(callId) {
      console.log('Call ended:', callId)
    },
    async handleAcceptCall(callId) {
      try {
        await this.$storex.calls.acceptCall(callId)
        this.$storex.session.onInfo('Call accepted')
      } catch (error) {
        console.error('Failed to accept call:', error)
        this.$storex.session.onError('Failed to accept call')
      }
    },
    async handleRejectCall(callId) {
      try {
        await this.$storex.calls.rejectCall(callId)
        this.$storex.session.onInfo('Call rejected')
      } catch (error) {
        console.error('Failed to reject call:', error)
        this.$storex.session.onError('Failed to reject call')
      }
    }
  }
}
</script>
