      </div>

      <!-- Footer -->
      <div class="shrink-0 border-t border-base-content/5 px-2 py-3">
        <div class="flex items-center justify-between px-3 py-2.5 rounded-xl hover:bg-white/5 transition-colors cursor-pointer">
          <div class="grow flex items-center gap-3 flex-1">
            <UserInfo>
              <template #trigger="{ togglePanel }">
                <button
                  class="btn btn-xs btn-ghost p-1 w-6 h-6 min-h-0"
                  @click="togglePanel"
                  :class="dailyLimitStatus === 'exceeded' ? 'text-error' : dailyLimitStatus === 'warning' ? 'text-warning' : 'text-info'"
                >
                  <div class="avatar tooltip" :data-tip="$user.username">
                    <div class="w-8">
                      <img :src="$user.avatar">
                    </div>
                  </div>
                </button>
              </template>
            </UserInfo>
            <div class="flex justify-between">
              <div class="flex-1 min-w-0">
                <div class="text-sm  truncate">{{ userName }}</div>
                <div class="text-xs text-base-content/40">{{ userSubtitle }}</div>
              </div>
              <button class="p-1 text-base-content/30 hover:text-base-content/80 transition-colors">
                <i class="fas fa-chevron-down text-xs"></i>
              </button>
            </div>
            <MainMenu
              :is-project-admin="isProjectAdmin"
              @close="handleClose"
            >
              <i class="fa-solid fa-ellipsis-vertical"></i>
            </MainMenu>
          </div>
        </div>
      </div>
    </aside>
  </div>

  <!-- Desktop Sidebar -->
  <aside
    v-else
    ref="sidebarEl"
    class="flex flex-col h-full shrink-0 border-r border-base-content/5 transition-all duration-200"
    :class="[isCollapsed ? 'w-20' : 'w-64']"
  >
    <!-- Header Section -->
    <div class="px-3 py-4 shrink-0 border-b border-base-content/5">
      <div class="flex items-center justify-between gap-2">
        <div v-if="!isCollapsed" class="flex items-center shrink-0 gap-2 flex-1">
          <button
            class="click w-6 h-6 rounded border border-base-content/20 flex items-center justify-center hover:bg-white/5 transition-colors"
            @click="toggleCollapse"
            title="Toggle sidebar"
          >
            <i class="fa-solid fa-angle-left text-base-content/40 text-xs"></i>
          </button>
          <span class="text-lg font-semibold">
            <span class="text-codx-secondary">codx-</span>
            <span class="text-codx-secondary">junior</span>
          </span>
        </div>
        <div v-else class="flex justify-center w-full">
          <button
            class="click w-6 h-6 flex items-center justify-center hover:bg-white/5 transition-colors"
            title="Expand sidebar"
            @click="toggleCollapse()"
          >
            <img class="w-full" src="/only_icon.png" />
          </button>
        </div>

        <div v-if="!isCollapsed" class="flex items-center gap-2">
          <Notifications />
        </div>        
      </div>
    </div>

    <!-- Scrollable Content Area -->
    <div class="flex-1 overflow-y-auto flex flex-col">
      <!-- Apps Section -->
      <AppsSection
        :is-collapsed="isCollapsed"
        :more-expanded="moreExpanded"
        @update:moreExpanded="moreExpanded = $event"
        @close="handleClose"
        @toggle-collapse="toggleCollapse"
      />

      <!-- Workspaces Section -->
      <WorkspacesSection
        :workspace-apps="workspaceApps"
        :is-collapsed="isCollapsed"
        :current-workspace-id="currentWorkspaceId"
        @close="handleClose"
      />

      <!-- Recents Section -->
      <RecentsSection
        :is-collapsed="isCollapsed"
        :is-mobile="false"
        @select-chat="handleSelectChat"
      />
    </div>

    <!-- Footer -->
    <div class="shrink-0 border-t border-base-content/5 px-2 py-3">
      <div v-if="!isCollapsed" class="flex items-center justify-between gap-3 px-3 py-2.5 rounded-xl hover:bg-white/5 transition-colors cursor-pointer">
        <UserInfo>
          <template #trigger="{ togglePanel }">
            <div class="flex gap-3 items-center flex-1 min-w-0">
              <button
                class="btn btn-xs btn-ghost p-1 w-6 h-6 min-h-0 shrink-0"
                @click="togglePanel"
                :class="dailyLimitStatus === 'exceeded' ? 'text-error' : dailyLimitStatus === 'warning' ? 'text-warning' : 'text-info'"
              >
                <div class="avatar tooltip" :data-tip="$user.username">
                  <div class="w-8">
                    <img :src="$user.avatar">
                  </div>
                </div>
              </button>
              <div class="flex-1 min-w-0">
                <div class="text-sm  truncate">{{ userName }}</div>
                <div class="text-xs"
                  :class="connected ? 'text-success/60': 'text-error'"
                >{{ connected ? 'online': 'offline' }}</div>
              </div>
            </div>
          </template>
        </UserInfo>
        <div class="flex items-center gap-2 shrink-0">
          <MainMenu
            :is-project-admin="isProjectAdmin"
            @close="handleClose"
          >
            <i class="fa-solid fa-ellipsis-vertical"></i>
          </MainMenu>
        </div>
      </div>

      <!-- Collapsed Footer - Icon Only -->
      <div v-else class="flex items-center justify-center gap-3 py-2">
        <UserInfo>
          <template #trigger="{ togglePanel }">
            <button
              class="btn btn-xs btn-ghost p-1 w-6 h-6 min-h-0"
              @click="togglePanel"
              :class="dailyLimitStatus === 'exceeded' ? 'text-error' : dailyLimitStatus === 'warning' ? 'text-warning' : 'text-info'"
            >
              <div class="avatar tooltip tooltip-right" :data-tip="$user.username">
                <div class="w-8">
                  <img :src="$user.avatar">
                </div>
              </div>
            </button>
          </template>
        </UserInfo>
        <MainMenu
          :is-project-admin="isProjectAdmin"
          @close="handleClose"
        >
          <i class="fa-solid fa-ellipsis-vertical text-xs"></i>
        </MainMenu>
      </div>
    </div>
  </aside>

  <!-- Incoming Call Notification -->
  <CallNotification
    :call="incomingCall"
    @accept="handleAcceptCall"
    @reject="handleRejectCall"
  />
</template>

<script>
export default {
  props: {
    isMobile: { type: Boolean, default: false },
    isMobileExpanded: { type: Boolean, default: false }
  },
  emits: ['settings', 'close'],
  data() {
    return {
      dailyLimitStatus: 'normal',
      moreExpanded: false
    }
  },
  computed: {
    isCollapsed() {
      return this.$storex.ui.sidebarCollapsed
    },
    workspaceApps() {
      return this.$projects.projectApps || []
    },
    currentUser() {
      return this.$storex?.users?.user || this.$user
    },
    hasWorkspaceApps() {
      return this.workspaceApps && this.workspaceApps.length > 0
    },
    isProjectAdmin() {
      return this.$users?.isProjectAdmin || false
    },
    currentWorkspaceId() {
      return this.$storex.$router.$navigation.getWorkspaceId()
    },
    isDesktopMode() {
      return this.$storex.$router.$navigation.isDesktopMode
    },
    userName() { 
      return this.$users.user?.username 
    },
    userSubtitle() {
      const email = this.$users.user?.email
      return email && email.length > 20 ? email.substring(0, 20) + '...' : email
    },
    connected() {
      return this.$session.connected
    },
    incomingCall() {
      const calls = this.$storex.calls.allIncomingCalls
      return calls.length > 0 ? calls[0] : null
    }
  },
  watch: {
    isMobileExpanded(val) {
      if (this.isMobile) {
        this.$storex.ui.setSidebarCollapsed(!val)
      }
    }
  },
  methods: {
    toggleCollapse() {
      this.$storex.ui.setSidebarCollapsed(!this.isCollapsed)
    },
    handleClose() {
      if (this.isMobile) {
        this.$storex.ui.setSidebarCollapsed(true)
      }
      this.$emit('close')
    },
    handleSelectChat(chat) {
      this.$chats.setActiveChat(chat)
      if (this.isMobile) {
        this.handleClose()
      }
    },
    handleCallInitiated(callId) {
      console.log('Call initiated:', callId)
    },
    handleCallEnded(callId) {
      console.log('Call ended:', callId)
    },
    async handleAcceptCall(callId) {
      try {
        await this.$storex.calls.acceptCall(callId)
        this.$storex.session.onInfo('Call accepted')
      } catch (error) {
        console.error('Failed to accept call:', error)
        this.$storex.session.onError('Failed to accept call')
      }
    },
    async handleRejectCall(callId) {
      try {
        await this.$storex.calls.rejectCall(callId)
        this.$storex.session.onInfo('Call rejected')
      } catch (error) {
        console.error('Failed to reject call:', error)
        this.$storex.session.onError('Failed to reject call')
      }
    }
  }
}
</script>

<style scoped>
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.animate-fade-in {
  animation: fadeIn 0.2s ease-out forwards;
}
</style>
```

---

## Summary of Changes

| Change | Impact |
|--------|--------|
| ✅ Removed `setupResizeObserver()` method | Eliminates auto-collapse logic that overwrites user preference |
| ✅ Removed ResizeObserver initialization/cleanup | Simplifies component lifecycle, removes conflicting state changes |
| ✅ Removed `resizeObserver` data property | Cleans up unused state |
| ✅ Removed `mounted()` and `beforeUnmount()` hooks | No longer needed without observer |
| ✅ Removed `sidebarInitialized` from state | No guard condition needed; state always saves |
| ✅ Kept `toggleCollapse()` button logic | Manual control remains the only way to change collapsed state |

**Result:** Sidebar collapsed state now persists correctly across sessions because it's only controlled by explicit user action via the toggle button.

